-- Release 2026-11-21 - Phase P5 (DEC-65; Q10 user, Q20 PROVISIONAL, Q26 user): transfer slips
-- generated by the Replacement Manager (multi-GS, one slip per Intermediate Store), Edit Requests to
-- Management / Super Admin, slips voided when a locked GS is edited.
--
-- Apply to production AFTER migration 20261121000100_p5_transfer_slips.sql and after deploying the
-- P5 backend + frontend. Idempotent; safe to re-run:
--   psql "<admin url>" -X -v ON_ERROR_STOP=1 -f supabase/snippets/release_20261121_p5_transfer_slips.sql
-- Same configuration as supabase/seed.sql (phase prompts §0 rule 3).
begin;

-- 1. Status label (GS_STATUS)
insert into public.option_items (option_set_id, code, label, allowed_status, rule_text, next_action_text,
                                 remarks, system_behavior, required_fields, sort_order, source_ref)
select os.id, 'TRANSFER_SLIP_GENERATED', 'Transfer Slip Generated', 'YES', null, null, null, null,
       '[]'::jsonb, 73, 'DEC-65'
  from public.option_sets os
 where os.code = 'GS_STATUS'
on conflict (option_set_id, code) do nothing;

-- 2. Grants: the RM generates slips and sends edit requests; Management sees them (and resolves
--    edit requests through itemization.configure, granted in P4). Super Admin: the migration.
insert into public.role_permissions (role_id, permission_id, scope)
select r.id, p.id, 'all'
  from (values ('REPLACEMENT_MANAGER', 'view'), ('REPLACEMENT_MANAGER', 'create'),
               ('MANAGEMENT', 'view')) as v(role_code, action)
  join public.roles r on r.code = v.role_code
  join public.permissions p on p.module_code = 'transfer_slips' and p.action = v.action
on conflict (role_id, permission_id) do nothing;

-- 3. Menus (journey catalogue entries come with the migration)
insert into public.role_journey_steps (role_id, journey_step_id, sort_order)
select r.id, s.id, v.ord
  from (values ('REPLACEMENT_MANAGER', 'TRANSFER_SLIPS', 10),
               ('MANAGEMENT', 'EDIT_REQUESTS', 10)) as v(role_code, step_code, ord)
  join public.roles r on r.code = v.role_code
  join public.journey_steps s on s.code = v.step_code
on conflict (role_id, journey_step_id) do nothing;

-- 4. Notification rules (event types come with the migration)
insert into public.notification_rules
  (event_type, name, include_context_recipients, recipient_role_codes, channels, priority, is_active)
select v.event_type, v.name, true, v.roles, array['IN_APP'], v.priority, true
  from (values
    ('TRANSFER_SLIP_VOIDED', 'RM: transfer slip voided, regenerate it', array['REPLACEMENT_MANAGER'], 'HIGH'),
    ('GS_EDIT_REQUESTED', 'Management & Super Admin: edit request for a locked goods slip', array['MANAGEMENT', 'SUPER_ADMIN'], 'HIGH'),
    ('GS_EDIT_REQUEST_RESOLVED', 'RM: edit request resolved', array['REPLACEMENT_MANAGER'], 'NORMAL')
  ) as v(event_type, name, roles, priority)
 where not exists (select 1 from public.notification_rules r where r.event_type = v.event_type);

-- 5. Report: GSs waiting for their transfer slip
do $$
declare
  v_pending integer;
begin
  select count(*) into v_pending from public.goods_slips where status = 'PENDING_TRANSFER_SLIP';
  raise notice 'DEC-65: % GS(s) in PENDING_TRANSFER_SLIP (Transfer Slips menu of the RM)', v_pending;
end
$$;

commit;
